function sql(value) {
  if (value === undefined || value === null || String(value).trim() === '') return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}
function sqlJson(value) {
  return sql(JSON.stringify(value ?? {})) + '::jsonb';
}
function parseJson(value, fallback) {
  if (value == null) return fallback;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return fallback; }
  }
  return value;
}
function toArray(value, fallback = []) {
  if (Array.isArray(value)) return value.map(String).filter(Boolean);
  if (typeof value === 'string' && value.trim()) return value.split(/[,;\n]/).map((x) => x.trim()).filter(Boolean);
  return fallback;
}
function unique(values) {
  return [...new Set(values.filter(Boolean).map(String))];
}
function normalizePromptPack(raw, row) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const brief = parseJson(row.brief, {});
  const sceneAvoidRules = toArray(parseJson(row.sceneAvoidRules, []), []);
  const briefAvoidRules = toArray(brief.avoidRules || brief.avoid_rules, []);
  const referenceImages = parseJson(row.referenceImages, []);
  const identityReminders = unique(source.identityReminders || [
    `${row.avatarDisplayName || row.avatar} must remain visually consistent with approved reference images`,
    'photorealistic Colombian lifestyle creator',
    'natural expression, believable candid presence, warm approachable energy',
    'elegant without luxury obsession or artificial influencer stiffness'
  ]);
  const sceneDetails = String(source.sceneDetails || [
    brief.visualIntent || row.sceneVisualIntent || row.sceneDescription,
    brief.sceneNotes || row.scenePromptNotes,
    brief.captionAngle || row.sceneContentAngle
  ].filter(Boolean).join(' ')).trim();
  const visualAvoidRules = unique([
    ...(source.visualAvoidRules || []),
    ...briefAvoidRules,
    ...sceneAvoidRules,
    'cartoon, anime, illustration, CGI look',
    'plastic skin, distorted face, wrong identity',
    'extra fingers, bad hands, bad anatomy',
    'overprocessed beauty filter, fake luxury, product-ad stiffness'
  ]);
  const positivePrompt = String(source.positivePrompt || [
    row.avatarDisplayName || row.avatar,
    brief.visualIntent || row.sceneVisualIntent || row.sceneDescription,
    sceneDetails,
    brief.emotionalTone || row.sceneAllowedMood,
    'photorealistic, candid lifestyle photography, natural skin texture, consistent identity, soft realistic light, high quality'
  ].filter(Boolean).join(', ')).trim();
  const negativePrompt = String(source.negativePrompt || visualAvoidRules.join(', ')).trim();
  return {
    positivePrompt,
    negativePrompt,
    identityReminders,
    sceneDetails,
    visualAvoidRules,
    referenceImages,
    suggestedFormat: String(source.suggestedFormat || brief.suggestedFormat || row.format || 'feed-post'),
    comfyHints: {
      aspectRatio: source.comfyHints?.aspectRatio || (row.format === 'story' ? '9:16' : '4:5'),
      outputIntent: source.comfyHints?.outputIntent || 'publication-candidate',
      assetType: 'raw-image'
    },
    comfyReferencePolicy: {
      contractVersion: 'comfy-reference-image-v1',
      loadImageRequiresComfyInputName: true,
      minioObjectPathIsNotComfyInput: true
    },
    source: {
      publicationJobId: row.publicationJobId,
      generatedFrom: 'publication-brief',
      generator: 'n8n-publication-prompt-pack-v2'
    }
  };
}
const row = $input.first()?.json || {};
if (row.ok === false || row.ok === 'f' || !row.publicationJobId) {
  const error = row.error || 'Publication job not found';
  return [{ json: { query: `SELECT false AS ok, ${sql(error)} AS error;` } }];
}
if (!row.brief && !row.manualPromptPack) {
